anna@sklep01:~$ sed -n '/listen 443/,/^}/p' /etc/nginx/sites-available/sklep
    listen 443 ssl; # managed by Certbot
    listen [::]:443 ssl;
    http2 on;
    ssl_certificate /etc/letsencrypt/live/sklep.firma.example/fullchain.pem; # managed by Certbot
    ssl_certificate_key /etc/letsencrypt/live/sklep.firma.example/privkey.pem; # managed by Certbot
    include /etc/letsencrypt/options-ssl-nginx.conf; # managed by Certbot

    client_max_body_size 20m;
    add_header Strict-Transport-Security "max-age=31536000" always;
    add_header X-Content-Type-Options nosniff always;

    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 5s;
        proxy_read_timeout 60s;
    }
    location /actuator/ { return 404; }

    error_page 502 503 504 /serwis.html;
    location = /serwis.html { root /var/www/serwis; internal; }
}
